package driver

// The files the driver writes, pinned without any other implementation: an existing data dir must stay readable, so the
// tables, indexes, column values, _schema hashes, outbox rows, stored JSON, password hashes and blob sidecars of a fixed
// write sequence are compared with testdata/layout-golden.json. That file was generated by the TypeScript driver this
// one replaced. After a deliberate change (a new index): OPM_UPDATE_LAYOUT_GOLDEN=1 go test ./internal/cloud/driver -run TestLayoutGolden

import (
	"bytes"
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"testing"

	"opm/agent/internal/cloud/doc"
)

func fixture(t testing.TB) (*doc.Map, []string) {
	_, f, _, _ := runtime.Caller(0)
	raw, err := os.ReadFile(filepath.Join(filepath.Dir(f), "testdata/fixture.json"))
	must(t, err)
	m, err := doc.ParseMap(raw)
	must(t, err)
	return m, m.Keys()
}

func goWriteAll(t *testing.T, p *Ports) {
	fx, keys := fixture(t)
	st := p.Store
	for _, k := range keys {
		s, err := doc.EncodeStored(fx.Val(k))
		must(t, err)
		d, err := DecodeDoc(s)
		must(t, err)
		must(t, st.Doc(k).Set(d))
	}
	// the same sequence as cross.ts write
	must(t, st.Doc("templates/T1").Update(doc.Obj("a.y", 3, "a.n.m", 1, "label", doc.DeleteField(), "cnt", doc.Increment(2), "arr", doc.ArrayUnion("x", doc.Obj("k", 1), "x"))))
	must(t, st.Doc("templates/T1").Set(doc.Obj("a", doc.Obj("z", 9, "q", doc.Obj("r", 1)), "arr", doc.ArrayRemove("x")), Merge))
	must(t, st.Doc("services/s1/images/v1").Update(doc.Obj("import.status", "done")))
	must(t, st.Doc("plain/gone").Set(doc.Obj("v", 1)))
	must(t, st.Doc("plain/gone").Delete())
	must(t, st.Doc("deployments/D2").Delete())
}

type tableDump map[string][]string

// dumpFile: every table and index, every row (typeof of ix columns included), _schema, _outbox without times.
func dumpFile(t *testing.T, file string) tableDump {
	db, err := sql.Open("sqlite", file)
	must(t, err)
	defer db.Close()
	out := tableDump{}
	rows, err := db.Query("SELECT type, name, tbl_name, sql FROM sqlite_master WHERE name NOT LIKE 'sqlite%' ORDER BY type, name")
	must(t, err)
	var tables []string
	for rows.Next() {
		var a, b, c string
		var s sql.NullString
		must(t, rows.Scan(&a, &b, &c, &s))
		out["#master"] = append(out["#master"], a+" "+b+" "+c+" "+s.String)
		if a == "table" {
			tables = append(tables, b)
		}
	}
	rows.Close()
	for _, tb := range tables {
		cols := []string{}
		r, err := db.Query("SELECT name FROM pragma_table_info(?)", tb)
		must(t, err)
		for r.Next() {
			var n string
			must(t, r.Scan(&n))
			cols = append(cols, n)
		}
		r.Close()
		sel := []string{}
		for _, c := range cols {
			if tb == "_outbox" && (c == "createdMs" || c == "leaseUntil") {
				continue
			}
			sel = append(sel, "typeof("+q(c)+")", "quote("+q(c)+")")
		}
		r, err = db.Query("SELECT " + strings.Join(sel, ",") + " FROM " + q(tb) + " ORDER BY 2")
		must(t, err)
		for r.Next() {
			vals := make([]any, len(sel))
			ptr := make([]any, len(sel))
			for i := range vals {
				ptr[i] = &vals[i]
			}
			must(t, r.Scan(ptr...))
			out[tb] = append(out[tb], fmt.Sprint(vals...))
		}
		r.Close()
	}
	return out
}

func compareDumps(t *testing.T, f string, a, b tableDump) {
	t.Helper()
	keys := map[string]bool{}
	for k := range a {
		keys[k] = true
	}
	for k := range b {
		keys[k] = true
	}
	for k := range keys {
		x, y := a[k], b[k]
		sort.Strings(x)
		sort.Strings(y)
		if strings.Join(x, "\n") != strings.Join(y, "\n") {
			t.Errorf("%s %s differ\nTS: %s\nGo: %s", f, k, strings.Join(x, "\n    "), strings.Join(y, "\n    "))
		}
	}
}

const goldenFile = "testdata/layout-golden.json"

// layoutDump is every file of a data dir written by the fixture sequence, auth tables left out (their rows hold random
// ids and hashes).
func layoutDump(t *testing.T, dir string) map[string]tableDump {
	t.Helper()
	out := map[string]tableDump{}
	for _, f := range []string{"db/global.sqlite", "db/deployments/D1.sqlite", "db/deployments/D2.sqlite"} {
		d := dumpFile(t, filepath.Join(dir, f))
		for k := range d {
			if strings.HasPrefix(k, "auth") {
				delete(d, k)
			}
		}
		for _, k := range []string{"#master", "_schema"} {
			var keep []string
			for _, s := range d[k] {
				if !strings.Contains(s, "auth") {
					keep = append(keep, s)
				}
			}
			d[k] = keep
		}
		for _, rows := range d {
			sort.Strings(rows)
		}
		out[f] = d
	}
	return out
}

// goldenRegistry is what the registry and trigger specs are pinned to.
func goldenRegistry() (*doc.Map, []any) {
	reg := doc.New()
	names := make([]string, 0, len(DefaultRegistry))
	for k := range DefaultRegistry {
		names = append(names, k)
	}
	sort.Strings(names)
	for _, k := range names {
		reg.Set(k, specJSON(DefaultRegistry[k]))
	}
	trig := []any{}
	for _, x := range TriggerSpecs {
		trig = append(trig, []any{x.Name, x.Kind, x.Pattern})
	}
	return reg, trig
}

func goldenJSON(t *testing.T, v any) string {
	t.Helper()
	b, err := doc.MarshalIndent(v, 1)
	must(t, err)
	return string(b)
}

func dumpValue(t *testing.T, files map[string]tableDump) *doc.Map {
	t.Helper()
	names := make([]string, 0, len(files))
	for f := range files {
		names = append(names, f)
	}
	sort.Strings(names)
	out := doc.New()
	for _, f := range names {
		m, err := doc.ToMap(map[string][]string(files[f]))
		must(t, err)
		out.Set(f, m)
	}
	return out
}

func TestLayoutGolden(t *testing.T) {
	dir := t.TempDir()
	p := open(t, dir, func(c *Config) { c.PublicURL, c.ConsoleURL = "http://cross.test", "http://console.test" })
	goWriteAll(t, p)
	p.Close()
	reg, trig := goldenRegistry()
	got := dumpValue(t, layoutDump(t, dir))
	raw, err := os.ReadFile(goldenFile)
	must(t, err)
	g, err := doc.ParseMap(raw)
	must(t, err)
	if os.Getenv("OPM_UPDATE_LAYOUT_GOLDEN") == "1" {
		g.Set("files", got).Set("registry", reg).Set("triggers", trig)
		must(t, os.WriteFile(goldenFile, append([]byte(goldenJSON(t, g)), '\n'), 0o644))
		return
	}
	eq(t, goldenJSON(t, reg), goldenJSON(t, g.Val("registry")), "index registry")
	eq(t, goldenJSON(t, trig), goldenJSON(t, g.Val("triggers")), "trigger specs")
	for _, f := range g.Map("files").Keys() {
		want, have := g.Map("files").Map(f), got.Map(f)
		for _, tb := range want.Keys() {
			if goldenJSON(t, want.Val(tb)) != goldenJSON(t, have.Val(tb)) {
				t.Errorf("%s table %s differs\nwant %s\ngot  %s", f, tb, goldenJSON(t, want.Val(tb)), goldenJSON(t, have.Val(tb)))
			}
		}
		eq(t, have.SortedKeys(), want.SortedKeys(), f)
	}
}

// The stored JSON decodes and encodes byte for byte, and the fixture answers queries through the index columns.
func TestStoredFormat(t *testing.T) {
	dir := t.TempDir()
	p := open(t, dir)
	goWriteAll(t, p)
	st := p.Store
	must(t, st.AllDocuments(func(path string, m *doc.Map) error {
		s, err := st.Doc(path).Get()
		must(t, err)
		again, err := EncodeDoc(s.Data())
		must(t, err)
		if again != *s.Raw() {
			t.Errorf("%s re-encoded differently:\n%s\n%s", path, *s.Raw(), again)
		}
		return nil
	}))
	u := data(t, st.Doc("accounts/U1"))
	if u.Val("ts") != (doc.Timestamp{Seconds: 1700000000, Nanos: 123000000}) {
		t.Fatal(u.Val("ts"))
	}
	if !bytes.Equal(u.Val("bytes").(doc.Bytes), []byte{0, 1, 2, 255}) {
		t.Fatal(u.Val("bytes"))
	}
	eq(t, ids(t, st.CollectionGroup("commits").OrderBy("seq")), []string{"c1", "c2", "c1"})
	eq(t, ids(t, st.Collection("deployments").Where("deleted", "==", false)), []string{"D1"})
	eq(t, ids(t, st.Collection("deployments").Where("slug", "==", "d-two")), []string{})
	eq(t, ids(t, st.Collection("auditLog").Where("_actionKeys", "array-contains", "x.")), []string{"A1"})
	eq(t, ids(t, st.Collection("agentNonces").Where("expiresAt", ">", doc.TimestampFromMillis(1800000000000))), []string{"N1"})
}

// Credentials and blob sidecars of an existing data dir keep working.
func TestStoredCredentialsAndSidecars(t *testing.T) {
	raw, err := os.ReadFile(goldenFile)
	must(t, err)
	g, err := doc.ParseMap(raw)
	must(t, err)
	dir := t.TempDir()
	p := open(t, dir)
	u, err := p.Auth.CreateUser(CreateUserInput{Email: "Ts.User@Example.com", Password: Ptr("another-password"), DisplayName: Ptr("TS User")})
	must(t, err)
	must(t, p.Store.Doc("authUsers/"+u.UID).Update(doc.Obj("passwordHash", g.Str("passwordHash"))))
	_, err = p.Auth.CheckPassword("ts.user@example.com", "ts-password-1")
	must(t, err)
	if _, err := p.Auth.CheckPassword("ts.user@example.com", "wrong"); err == nil {
		t.Fatal("wrong password")
	}
	must(t, p.Blobs.Put("files/a b/ü.txt", []byte("hello cross"), PutOptions{ContentType: "text/x-cross", CacheControl: "private, max-age=9", Meta: map[string]string{"opmSha256": "abc", "z": "1", "a": "2"}}))
	side := filepath.Join(dir, "blobmeta/files/a b/ü.txt.json")
	b, err := os.ReadFile(side)
	must(t, err)
	mine, err := doc.ParseMap(b)
	must(t, err)
	old := g.Map("sidecar")
	eq(t, mine.Keys(), old.Keys(), "sidecar shape")
	must(t, os.WriteFile(side, []byte(doc.MarshalString(old)), 0o644))
	h, err := p.Blobs.Head("files/a b/ü.txt")
	must(t, err)
	eq(t, h.Size, 11)
	eq(t, h.ContentType, "text/x-cross")
	eq(t, p.Blobs.CacheControl("files/a b/ü.txt"), "private, max-age=9")
	eq(t, h.Meta["opmSha256"], "abc")
	url, err := p.Blobs.SignedReadURL("files/a b/ü.txt", 60_000_000_000, `attachment; filename="ü b.txt"`)
	must(t, err)
	r := blobReq(p.Blobs, strings.TrimPrefix(url, "http://opm.test"), nil, "GET")
	eq(t, r.Code, 200)
	eq(t, r.Body.String(), "hello cross")
	eq(t, r.Header()["Content-Type"], []string{"text/x-cross"})
	eq(t, r.Header()["Content-Disposition"], []string{`attachment; filename="ü b.txt"`})
}
